-- D&D 3.0 Psionics Handbook source-backed legacy rules catalog.
-- These procedures are preserved for source fidelity but are disabled by default in the D&D 3.5 ruleset because Expanded Psionics Handbook revises the system.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('ph3e-3.0','psionics-handbook-3-0','Psionics Handbook','PsiHB','Wizards of the Coast','dnd','3.0',
        'D&D 3.0 Psionics Handbook, including the official errata appended to the supplied source PDF.',NULL,1,0,NULL);

WITH desired(slug,name,source_page,category,kind,summary,tags,mechanics) AS (VALUES
  ('ph3e-manifesting-powers','Manifesting Powers (3.0)','31-32','psionics','rule','A psion or psychic warrior chooses a known power of an available level, pays its power-point cost from the daily reserve, concentrates, and manifests the effect without preparing powers ahead of time.','["psionics","3.0","legacy","manifesting"]','{"prepare_ahead":false,"pays_power_points":true}'),
  ('ph3e-psionic-components','Psionic Manifestation Components (3.0)','31-32,40','psionics','rule','Psionic powers and abilities are activated mentally, have no verbal, somatic, or material components, and armor does not interfere with their use.','["psionics","3.0","legacy","components"]','{"verbal":false,"somatic":false,"material":false,"armor_interference":false}'),
  ('ph3e-power-key-ability','Discipline Key Ability Requirement (3.0)','8-9,32','psionics','rule','Each discipline uses its own key ability, and manifesting a leveled power requires that discipline''s key ability score to be at least 10 + the power level.','["psionics","3.0","legacy","disciplines","abilities"]','{"minimum_key_ability":"10 + power level"}'),
  ('ph3e-power-save-dc','Rolled Power Saving Throw DC (3.0)','8-9,33','psionics','rule','The default Psionics Handbook save DC is set by the manifester rolling d20 and adding the power level and the discipline''s key ability modifier.','["psionics","3.0","legacy","saving-throws","dc"]','{"formula":"d20 + power level + key ability modifier"}'),
  ('ph3e-fixed-power-save-dc-variant','Variant: Fixed Power Saving Throw DC (3.0)','33','psionics','rule','An optional variant replaces the rolled save DC with the spell-like formula 10 + power level + key ability modifier.','["psionics","3.0","legacy","variant","saving-throws"]','{"formula":"10 + power level + key ability modifier"}'),
  ('ph3e-concentration-manifesting','Concentration while Manifesting (3.0)','34-35','psionics','rule','Manifesting requires concentration, and damage, hostile effects, movement, weather, grappling, or other distractions can require a Concentration check or cause the power to fail.','["psionics","3.0","legacy","concentration"]','{}'),
  ('ph3e-manifest-defensively','Manifesting Defensively (3.0)','35','psionics','rule','A manifester can attempt to avoid attacks of opportunity by succeeding on the defensive-manifestation Concentration check; failure prevents the power from being manifested.','["psionics","3.0","legacy","concentration","attacks-of-opportunity"]','{}'),
  ('ph3e-manifester-level','Manifester Level (3.0)','35','psionics','rule','A power''s level-dependent effects and manifester-level checks normally use the manifester''s level in the class supplying the power.','["psionics","3.0","legacy","manifester-level"]','{}'),
  ('ph3e-power-resistance','Power Resistance (3.0)','33-35','psionics','rule','When power resistance applies, the manifester makes a manifester-level check of 1d20 + manifester level and must meet the target''s power resistance.','["psionics","3.0","legacy","power-resistance"]','{"check":"1d20 + manifester level","success":"result >= power resistance"}'),
  ('ph3e-psionics-magic-transparency','Psionics-Magic Transparency (3.0)','36','psionics','rule','The default 3.0 rules allow psionic powers and magic to interact: psionic abilities can be subject to spell resistance, dispel magic, and areas that suppress either magic or psionics.','["psionics","3.0","legacy","magic","transparency"]','{"default":true,"spell_resistance_applies":true,"dispel_magic_applies":true}'),
  ('ph3e-psionics-are-different','Variant: Psionics Are Different (3.0)','39','psionics','subsystem','The optional non-transparency system separates psionic and magical defenses, detection, dispelling, and resistance, including separate power resistance and weaker cross-system countermeasures.','["psionics","3.0","legacy","variant","magic"]','{"psionics_magic_transparency":false}'),
  ('ph3e-zero-level-talents','0-Level Psionic Talents (3.0)','10,37','psionics','rule','A psion can manifest known 0-level talents for free a number of times per day equal to psion level + 3; further talent manifestations that day cost 1 power point each.','["psionics","3.0","legacy","talents","power-points"]','{"free_uses_per_day":"psion level + 3","cost_after_free_uses":1}'),
  ('ph3e-multiclass-power-point-pool','Multiclass Psionic Power Point Pool (3.0)','16,37','psionics','rule','A multiclass psionic character combines available power points from psion and psychic-warrior classes into one reserve, while powers known and class advancement remain class-specific.','["psionics","3.0","legacy","multiclass","power-points"]','{"shared_power_point_pool":true,"powers_known_separate":true}'),
  ('ph3e-psionic-special-abilities','Psionic Spell-Like Abilities (3.0)','40','psionics','rule','Freely manifested psionic abilities generally operate like spell-like abilities, require no components, ignore armor, and use a manifestation time of one action unless their description says otherwise.','["psionics","3.0","legacy","special-abilities"]','{"default_manifestation_time":"1 action","components":false,"armor_interference":false}'),
  ('ph3e-psionic-combat','Psionic Combat (3.0)','40-44','psionics','subsystem','The 3.0 psionic-combat subsystem pits psionic attack modes against defense modes, with specialized modifiers and ability-score damage; nonpsionic targets interact with the subsystem differently.','["psionics","3.0","legacy","psionic-combat"]','{"attack_modes":5,"defense_modes":5}'),
  ('ph3e-psionic-attack-modes','Psionic Attack Modes (3.0)','42','psionics','table','The five attack modes are mind thrust, ego whip, id insinuation, psychic crush, and mind blast, each with its own cost, attack characteristics, and effective power level for Concentration checks.','["psionics","3.0","legacy","psionic-combat","attack-modes"]','{"modes":["mind thrust","ego whip","id insinuation","psychic crush","mind blast"],"effective_levels":{"mind thrust":1,"ego whip":2,"id insinuation":2,"psychic crush":3,"mind blast":5}}'),
  ('ph3e-psionic-defense-modes','Psionic Defense Modes (3.0)','42-44','psionics','table','The five defense modes are thought shield, mental barrier, empty mind, intellect fortress, and tower of iron will, used to reduce or redirect the effects of psionic attack modes.','["psionics","3.0","legacy","psionic-combat","defense-modes"]','{"modes":["thought shield","mental barrier","empty mind","intellect fortress","tower of iron will"]}'),
  ('ph3e-psionic-combat-actions','Psionic Combat and Attacks of Opportunity (3.0)','42,errata','psionics','rule','Official errata classifies attack and defense modes as supernatural; using an attack mode provokes an attack of opportunity, while using a defense mode does not.','["psionics","3.0","legacy","psionic-combat","errata"]','{"attack_modes_supernatural":true,"defense_modes_supernatural":true,"attack_mode_provokes_aoo":true,"defense_mode_provokes_aoo":false}'),
  ('ph3e-psionic-item-transparency','Magic-Psionic Item Equivalencies (3.0)','121-122','psionics','rule','Under default transparency, psionic items and magic items use parallel activation, saving throw, damage, and interaction rules where the two systems are equivalent.','["psionics","3.0","legacy","items","transparency"]','{}'),
  ('ph3e-psionic-item-creation','Creating Psionic Items (3.0)','138','crafting','subsystem','Psionic item creation uses the appropriate psionic item-creation feat, access to required powers, time and gp costs, and XP expenditures according to the item category.','["psionics","3.0","legacy","items","crafting"]','{}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'ph3e-3.0-rule-' || d.slug, 'ph3e-3.0', d.source_page, d.slug, d.name, d.summary, d.summary,
  0,NULL,1,d.category,d.kind,1,0,NULL,NULL,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.slug=d.slug AND r.owner_user_id IS NULL
);
